class SinglyLinkedList:
  def __init__(self):
    self.head = None
    self._size = 0

  def size(self):
    return self._size

  def push_front(self, val):
    new = Node(val)
    new.next = self.head
    self.head = new
    self._size += 1

  def pop_front(self):
    if not self.head:
      return None
    val = self.head.val
    self.head = self.head.next
    self._size -= 1
    return val

  def push_back(self, val):
    new = Node(val)
    self._size += 1
    if not self.head:
      self.head = new
      return
    cur = self.head
    while cur.next:
      cur = cur.next
    cur.next = new

  def pop_back(self):
    if not self.head:
      return None
    self._size -= 1
    if not self.head.next:
      val = self.head.val
      self.head = None
      return val
    cur = self.head
    while cur.next and cur.next.next:
      cur = cur.next
    val = cur.next.val
    cur.next = None
    return val

  def contains(self, val):
    cur = self.head
    while cur:
      if cur.val == val:
        return cur
      cur = cur.next
    return None

