class SinglyLinkedList {
  constructor() {
    this.head = null;
    this._size = 0;
  }

  size() {
    return this._size;
  }

  pushFront(val) {
    const newNode = new Node(val);
    newNode.next = this.head;
    this.head = newNode;
    this._size++;
  }

  popFront() {
    if (!this.head) {
      return null;
    }
    const val = this.head.val;
    this.head = this.head.next;
    this._size--;
    return val;
  }

  pushBack(val) {
    const newNode = new Node(val);
    this._size++;
    if (!this.head) {
      this.head = newNode;
      return;
    }
    let cur = this.head;
    while (cur.next) {
      cur = cur.next;
    }
    cur.next = newNode;
  }

  popBack() {
    if (!this.head) {
      return null;
    }
    this._size--;
    if (!this.head.next) {
      const val = this.head.val;
      this.head = null;
      return val;
    }
    let cur = this.head;
    while (cur.next && cur.next.next) {
      cur = cur.next;
    }
    const val = cur.next.val;
    cur.next = null;
    return val;
  }

  contains(val) {
    let cur = this.head;
    while (cur) {
      if (cur.val === val) {
        return cur;
      }
      cur = cur.next;
    }
    return null;
  }
