class Node {
  int val;
  Node next;

  Node(int x) {
    val = x;
    next = null;
  }
}

class SinglyLinkedList {
  private Node head;
  private int size;

  public SinglyLinkedList() {
    head = null;
    size = 0;
  }

  public int size() {
    return size;
  }

  public void pushFront(int val) {
    Node newNode = new Node(val);
    newNode.next = head;
    head = newNode;
    size++;
  }

  public void pushBack(int val) {
    Node newNode = new Node(val);
    if (head == null) {
      head = newNode;
    } else {
      Node cur = head;
      while (cur.next != null) {
        cur = cur.next;
      }
      cur.next = newNode;
    }
    size++;
  }

  public Integer popFront() {
    if (head == null) {
      return null;
    }
    int val = head.val;
    head = head.next;
    size--;
    return val;
  }

  public Integer popBack() {
    if (head == null) {
      return null;
    }
    if (head.next == null) {
      int val = head.val;
      head = null;
      size--;
      return val;
    }
    Node cur = head;
    while (cur.next.next != null) {
      cur = cur.next;
    }
    int val = cur.next.val;
    cur.next = null;
    size--;
    return val;
  }

  public Node contains(int val) {
    Node cur = head;
    while (cur != null) {
      if (cur.val == val)
        return cur;
      cur = cur.next;
    }
    return null;
  }
}

